let gr;
let posX, posY, lastX, lastY;
let flag = false;
let count = 0;

let tx, txCloud;

let vs =
"precision mediump float;" +
"attribute vec3 aPosition;" +
"varying vec2 vUv;" +
"void main(){" +
"  vUv = (aPosition.xy + 1.0) * 0.5;" +
