"}";

function preload(){
	//txCloud = loadImage("https://openprocessing.org/sketch/1614378/files/cloud2.png");
	txCloud = loadImage("https://openprocessing.org/sketch/1614378/files/IMG_5705.JPG");
}

function setup() {
  createCanvas(1112, 834);
  gr = createGraphics(width,height,WEBGL);
	gr.setAttributes("alpha",true);
  _gl = gr._renderer;
  gl = _gl.GL;
  gr.directionalLight(255,255,255,0,0,-1);
  gr.ambientLight(64);
  gr.fill(255);
	gr.ortho();
  ChainGeom();

	// テクスチャ！
	tx = createGraphics(512, 512, WEBGL);
	tx.pixelDensity(1);
	tx.setAttributes("alpha", true);
  const sh = tx.createShader(vs, fs);
	tx.shader(sh);
	let col = HSV2RGB(0.06, 0.8, 0.6);
	sh.setUniform("uBaseColor", [col.r, col.g, col.b]);
	sh.setUniform("uTex", txCloud);
	tx.quad(-1,-1,-1,1,1,1,1,-1);

}

function draw() {
  background(0);
  if(flag){drawChainContinuous(80)}
  image(gr,0,0);
}

function ChainGeom(){
  let geom = new p5.Geometry();
  let cu = ChainUnit();
  geom.vertices = cu.v;
  geom.faces = cu.f;
	geom.uvs = cu.uv;
	geom.vertexNormals = cu.n;
  //geom.computeNormals();
  _gl.createBuffers("chain", geom);
}

function ChainUnit(){
  let v=[];
  let f=[];
	let uv = []; // UVを追加する
	let n = [];
	// Uについては外周で長さが0.5+0.5+0.25*TAUに対する割合
	// Vについては内側から外側へ...んー。
	// 0で外側から始まり内側へ。登ってzが最大で0.25でzが0で0.5でzが最小で0.75で1で戻る
	// Uサイドのへんな帯が消えない謎

	const L = 0.5 + 0.5 + 0.5 * Math.PI; 
  const r = 0.05;
  // (-0.25,0.25,0)～(0.25,0.25,0)のr太さの円柱
  for(let i=0;i<=40;i++){
    const x = map(i,0,40,-0.25,0.25);
    for(let k=0;k<=10;k++){
      const phi = Math.PI*2*k/10;
      v.push(createVector(x, 0.25+r*cos(phi),r*sin(phi)));
			n.push(createVector(0, cos(phi), sin(phi)));
			const _u = (x + 0.25) / L;
			const _v = phi / (Math.PI*2);
			uv.push(_u, _v);
    }
  }
  // (0.25,0.25,0)～(0.25,-0.25,0)のr太さのトーラスの一部
  for(let i=1;i<=40;i++){
    const theta = map(i,0,40,0,Math.PI);
    var x = 0.25 + 0.25 * sin(theta);
    const y = 0.25 * cos(theta);
    // ベクトル(sin(theta),cos(theta),0),(0,0,1)の組み合わせ
    for(let k=0;k<=10;k++){
      var phi = Math.PI*2*k/10;
      v.push(createVector(x+r*cos(phi)*sin(theta),
                          y+r*cos(phi)*cos(theta),
                          r*sin(phi)));
			n.push(createVector(cos(phi)*sin(theta), cos(phi)*cos(theta), sin(phi)));
			var _u = (0.5 + 0.25*theta) / L;
			var _v = phi / (Math.PI*2);
			uv.push(_u, _v);
    }
  }
	// (0.25,-0.25,0)～(-0.25,-0.25,0)のr太さの円柱
  for(let i=1;i<=40;i++){
    var x = map(i,0,40,0.25,-0.25);
    for(let k=0;k<=10;k++){
      var phi = Math.PI*2*k/10;
      v.push(createVector(x, -0.25-r*cos(phi),r*sin(phi)));
			n.push(createVector(0, -cos(phi), sin(phi)));
			var _u = (0.5 + 0.25*Math.PI + (0.25-x)) / L;
			var _v = phi / (Math.PI*2);
			uv.push(_u, _v);
    }
  }
	// (-0.25,-0.25,0)～(-0.25,0.25,0)のr太さのトーラスの一部
  for(let i=1;i<=40;i++){
    var theta = map(i,0,40,0,Math.PI);
    var x = -0.25 - 0.25 * sin(theta);
    var y = -0.25 * cos(theta);
    // ベクトル(sin(theta),cos(theta),0),(0,0,1)の組み合わせ
    for(let k=0;k<=10;k++){
      var phi = Math.PI*2*k/10;
      v.push(createVector(x-r*cos(phi)*sin(theta),
                          y-r*cos(phi)*cos(theta),
                          r*sin(phi)));
			n.push(createVector(-cos(phi)*sin(theta), -cos(phi)*cos(theta), sin(phi)));
			var _u = (0.5 + 0.25*Math.PI + 0.5 + 0.25*theta) / L;
			var _v = phi / (Math.PI*2);
			uv.push(_u, _v);
    }
  }
	// 重複頂点にしてnormalは別に計算。
  // 0,1,2,...,10,  11,12,13,...,21,  ...,  11*160, 11*160+1, ... 11*160+10.
  // [0,1,11],[1,11,12],[1,2,12],[2,12,13],...
  // 面張り
	// ループでの適切な処理は不要。
  for(let i=0;i<160;i++){
    for(let k=0;k<10;k++){
      const l = (k<9?k+1:0);
      const m = (i<159?i+1:0);
			//const m = i+1;
      f.push([i*11+k, i*11+k+1, (i+1)*11+k], [i*11+k+1, (i+1)*11+k, (i+1)*11+k+1]);
    }
  }
  // メッシュ3200枚
  return {v:v, f:f, n:n, uv:uv};
}

function drawChain(s=1){
  _gl.drawBuffersScaled("chain",s,s,s);
}

function mousePressed(){
  posX = (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))-width/2;
  posY = (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))-height/2;
  lastX = posX;
  lastY = posY;
  flag = true;
}

function mouseReleased(){
  flag = false;
}

function drawChainContinuous(size){
  let preX = posX;
  let preY = posY;
  const dx = ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))-width/2)-posX;
  const dy = ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))-height/2)-posY;
  posX += 0.1*dx;
  posY += 0.1*dy;
  for(let k=0;k<=100;k++){
    const ax = map(k,0,100,preX,posX);
    const ay = map(k,0,100,preY,posY);
    if(mag(ax-lastX,ay-lastY)>size*0.6){
      gr.push();
      gr.translate(ax,ay,0);
      gr.rotateZ(atan(dy/dx));
      gr.rotateX(PI/9+count*PI/2);
      count++;
			gr.texture(tx);
      drawChain(size);
      gr.pop();
      lastX = ax;
      lastY = ay;
    }
  }
}

// HSV→RGB変換。
// これはexportしてもいいかもしれない
function HSV2RGB(h, s, v){
  h = constrain(h, 0, 1);
  s = constrain(s, 0, 1);
  v = constrain(v, 0, 1);
  let _r = constrain(abs(((6 * h) % 6) - 3) - 1, 0, 1);
  let _g = constrain(abs(((6 * h + 4) % 6) - 3) - 1, 0, 1);
  let _b = constrain(abs(((6 * h + 2) % 6) - 3) - 1, 0, 1);
  _r = _r * _r * (3 - 2 * _r);
  _g = _g * _g * (3 - 2 * _g);
  _b = _b * _b * (3 - 2 * _b);
  let result = {};
  result.r = v * (1 - s + s * _r);
  result.g = v * (1 - s + s * _g);
  result.b = v * (1 - s + s * _b);
  return result;
}

